<script setup>import{Head}from'@inertiajs/vue3';import AppLayout from'../Layouts/AppLayout.vue';import EmptyState from'../Components/EmptyState.vue';defineProps({awards:Array,best:Object});</script><template><Head title="Hall of Fame"/><AppLayout><div class="rounded-3xl bg-[#143c2b] p-8 text-white sm:p-12"><p class="label !text-[#f4d35e]">Mandem legacy</p><h1 class="mt-3 text-5xl font-black tracking-tight">Hall of Fame.</h1><p class="mt-3 max-w-xl text-white/60">The season starts here. Every honour is permanent; every disaster is archived.</p></div><template v-if="awards.length"><div class="mt-7 grid gap-6 lg:grid-cols-2"><section class="card p-7"><h2 class="text-xl font-black">Most decorated</h2><div class="mt-5 space-y-3"><div v-for="(a,i) in awards" class="flex items-center gap-4 rounded-xl bg-black/[.025] p-4 dark:bg-white/[.03]"><b class="text-2xl text-[#b8a138]">{{i+1}}</b><span class="font-bold">{{a.manager}}</span><span class="ml-auto label">{{a.awards}} honours</span></div></div></section><section class="card p-7"><h2 class="text-xl font-black">Record book</h2><div v-if="best" class="mt-6 rounded-2xl bg-[#f4d35e] p-6 text-[#17241d]"><span class="label !text-black/50">Highest GW score</span><strong class="mt-2 block text-5xl">{{best.points}}</strong><p class="mt-2 font-bold">{{best.entry.manager_name}} · GW{{best.gameweek.number}}</p></div></section></div></template><EmptyState v-else class="mt-7" title="History begins this season" text="Weekly awards and all-time records will accumulate here automatically."/></AppLayout></template>
